INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (1,396,0,'Kompozisyon yazma asistanı','Kompozisyon başlığına ve türüne göre kompozisyon oluşturmaya yardımcı olur.','null','{"children": [{"children": [{"attributes": {"text": "Kompozisyon başlığı", "style": "titleMedium"}, "elementType": "Text"}, {"attributes": {"text": "*", "color": "error", "style": "bodySmall"}, "elementType": "Text"}], "attributes": {"horizontalArrangement": 2}, "elementType": "Row"}, {"attributes": {"label": "", "prompt": "Kompozisyon başlığı \"%s\".", "padding": {"top": 8}, "fillMaxWidth": true}, "elementType": "OutlinedTextField"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Kompozisyon türü", "style": "titleSmall"}, "elementType": "Text"}, {"children": [{"attributes": {"label": "Özel tür", "prompt": "Özel tür %s", "padding": {"top": 8}}, "elementType": "OutlinedTextField"}], "attributes": {"data": ["Anlatı metni", "Tartışmacı makale", "Açıklayıcı metin", "Lirik yazı", "Betimleyici yazı", {"type": "custom", "label": "Diğer"}], "prompt": "Tür \"%s\".", "fillMaxWith": true, "maxSelected": 1, "selectIndex": 0}, "elementType": "RowSelector"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Referans materyal", "style": "titleSmall"}, "elementType": "Text"}, {"attributes": {"prompt": "İçerik \"%s\" referans alınmalı.\n", "heightIn": {"max": 200, "min": 100}, "maxLines": 6, "maxLength": 500, "placeholder": "Referans materyali buraya girin...", "fillMaxWidth": true}, "elementType": "OutlinedTextField"}, {"attributes": {"size": "4"}, "elementType": "Spacer"}, {"attributes": {"text": "Kompozisyon Oluştur", "click": {"action": "submit", "target": "aiChat"}, "fillMaxWith": true}, "elementType": "Button"}], "attributes": {"padding": {"end": 15, "top": 15, "start": 15, "bottom": 15}, "verticalArrangement": 8}, "elementType": "LazyColumn"}','Kompozisyon yazma asistanı olmanı istiyorum, sağladığım başlık, materyal, anahtar kelimeler vb. temel alarak, Çin siyasi değerlerine ve kültürel arka planına uygun bir kompozisyon tasarlamama ve oluşturmama yardımcı ol. Verdiğim tema, örneğin "vatan sevgisi", "geleneksel kültür ve modern gelişim" veya "gençlik mücadelesi" gibi, yazma fikirleri, paragraf çerçevesi ve materyal önerileri sağlayabilirsin. Oluşturulan kompozisyonun olumlu olmasını, sosyalist temel değerleri yüceltmesini ve okuyucunun vatanseverlik duygularını ve ulusal gururunu uyandırmasını sağla. Oluşturma sürecinde, Çin ile tartışmalı sınır bölgeleri, hassas siyasi konular veya tartışmalı sıcak konularla ilgili herhangi bir şeyden kaçın, böylece kompozisyonun uyumlu ve olumlu etkisi olsun.',1786086278997);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (2,382,0,'Çocuk İsimlendirme Asistanı','Çocuklara isim verirken ismin benzersizliği, kültürel arka planı, anlamı ve sadeliği gibi boyutları dikkate alır','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "", "surname": "", "extraReq": "", "birthDate": "", "birthTime": "", "nameLength": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["text_surname", "field_surname", "spacer1", "text_gender", "picker_gender", "spacer2", "text_nameLength", "selector_nameLength", "spacer3", "text_birthDate", "input_birthDate", "spacer4", "text_birthTime", "input_birthTime", "spacer5", "text_extraReq", "field_extraReq", "spacer6", "button_submit"], "component": "Column"}, {"id": "text_surname", "text": "Çocuğun soyadı", "weight": "bold", "component": "Text"}, {"id": "field_surname", "label": "Lütfen çocuğun soyadını gir", "value": {"path": "/surname"}, "enabled": true, "component": "TextField"}, {"id": "spacer1", "height": 8, "component": "Spacer"}, {"id": "text_gender", "text": "Çocuğun cinsiyeti", "weight": "bold", "component": "Text"}, {"id": "picker_gender", "options": ["Erkek", "Kadın", "Bilinmiyor"], "selected": {"path": "/gender"}, "component": "ChoicePicker"}, {"id": "spacer2", "height": 8, "component": "Spacer"}, {"id": "text_nameLength", "text": "İsim karakter sayısı gereksinimi", "weight": "bold", "component": "Text"}, {"id": "selector_nameLength", "label": "Kelime sayısını seçin", "value": {"path": "/nameLength"}, "options": [{"label": "2 karakter", "value": "2"}, {"label": "3 karakter", "value": "3"}, {"label": "4 karakter", "value": "4"}], "spacing": 16, "component": "RowSelector", "maxSelected": 1}, {"id": "spacer3", "height": 8, "component": "Spacer"}, {"id": "text_birthDate", "text": "Doğum tarihi", "weight": "bold", "component": "Text"}, {"id": "input_birthDate", "mode": "date", "label": "Doğum tarihini seçin", "value": {"path": "/birthDate"}, "component": "DateInput"}, {"id": "spacer4", "height": 8, "component": "Spacer"}, {"id": "text_birthTime", "text": "Doğum saati", "weight": "bold", "component": "Text"}, {"id": "input_birthTime", "mode": "time", "label": "Doğum saatini seçin", "value": {"path": "/birthTime"}, "component": "TimeInput"}, {"id": "spacer5", "height": 8, "component": "Spacer"}, {"id": "text_extraReq", "text": "Diğer özel gereksinimler", "weight": "bold", "component": "Text"}, {"id": "field_extraReq", "label": "Kuşak, yasaklı karakterler, stil tercihi, özel karakter sayısı gibi", "value": {"path": "/extraReq"}, "enabled": true, "component": "TextField"}, {"id": "spacer6", "height": 12, "component": "Spacer"}, {"id": "button_submit", "label": "Tek tıkla isim oluştur", "action": {"event": {"name": "submit", "context": {"prompt": "Lütfen aşağıdaki bilgilere göre çocuğa isim öner: Soyadı ${surname}, cinsiyet ${gender}, isim uzunluğu gereksinimi ${nameLength} karakter, doğum tarihi ${birthDate}, doğum saati ${birthTime}, diğer gereksinimler: ${extraReq}. Lütfen özgünlük, kültürel arka plan, güzel anlam, sadelik ve okunabilirlik, beş element uyumu gibi boyutlardan en az 5 uygun isim öner, her isme ayrıntılı anlam, köken, uygunluk nedeni ve aynı isim oranı referansı ekle."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Profesyonel bir isim koyma uzmanısınız ve geleneksel kültür, modern estetik ve isim bilimi ilkelerine göre çocuklara isim koyma konusunda uzmansınız. Kullanıcı çocuk bilgilerini sağladığında, aşağıdaki boyutlardan kapsamlı bir şekilde isimler önereceksiniz: özgünlük (yaygın isimlerden kaçınma, düşük aynı isim oranı), kültürel arka plan (şiir ve deyimler, tarihsel köken), güzel anlam (ahlak, bilgelik, sağlık gibi semboller), basitlik ve okunabilirlik (basit yazım, akıcı telaffuz) ve Beş Element uyumu (doğum zamanına göre sekiz karakter analizi). Her önerilen isim için şunları ekleyin: 1. İsmin anlam analizi; 2. Kültürel kaynak veya ilham kaynağı; 3. Uygunluk gerekçesi (kullanıcı ihtiyaçlarına göre); 4. Aynı isim oranı referansı (yaygın, az, nadir gibi). Kullanıcı bilgileri eksikse, eksik öğeleri aktif olarak sorun (örneğin, sekiz karakter analizi için doğum zamanı). Çıktı formatı net olsun, Markdown ile madde işaretleri kullanın, dil anlaşılır olsun.',1786086282149);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (3,383,0,'Yüksek duygusal zeka yanıtı','Cebinizdeki iletişim danışmanı, iletişim sanatınızı kolayca geliştirir, her yanıtınıza sıcaklık ve bilgelik katar.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"style": "", "target": "", "content": "", "position": "", "background": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["target", "target_select", "content", "content_input", "bg", "bg_input", "style", "style_select", "position", "position_select", "submit"], "component": "Column"}, {"id": "target", "text": "Yanıt hedefi", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "target_select", "value": {"path": "/target"}, "options": ["Büyükler", "Patron", "İş arkadaşı", "Müşteri", "Arkadaş", "Partner", "Yabancılar"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "content", "text": "Karşı tarafın söylediği içerik", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "content_input", "value": {"path": "/content"}, "maxLines": 5, "minLines": 2, "component": "TextField", "placeholder": "Lütfen karşı tarafın söylediklerini gir", "supportingText": "Lütfen karşı tarafın orijinal sözlerini doğrudan gir"}, {"id": "bg", "text": "Diyalog bağlamı", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "bg_input", "value": {"path": "/background"}, "maxLines": 3, "minLines": 1, "component": "TextField", "placeholder": "Mevcut sahneyi ve arka plan bilgisini tanımla", "supportingText": "Örnek: Bir iş arkadaşımla proje görev dağılımı konusunda anlaşmazlık yaşadık, WeChat''te iletişim kuruyoruz"}, {"id": "style", "text": "Yanıt stili", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "style_select", "value": {"path": "/style"}, "options": ["Resmi iş", "Kısa ve net", "Dolaylı ve nazik", "Esprili ve nükteli", "Sıcak ve Samimi"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "position", "text": "Tutum eğilimi", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "position_select", "value": {"path": "/position"}, "options": ["Kabul", "Tarafsız", "Katılmıyorum"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "submit", "label": "Yüksek EQ Yanıtı Oluştur", "action": {"event": {"name": "submit", "context": {"prompt": "Yanıt hedefi: ${target}\nKarşı tarafın ifadesi: ${content}\nDiyalog bağlamı: ${background}\nYanıt stili: ${style}\nTutum eğilimi: ${position}\n\nLütfen 3 farklı stilde yüksek duygusal zekâlı yanıt seçeneği üretin, her birine kısa bir yorum ekleyin."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Çeşitli sosyal ortamlarda uygun, sıcak ve bilge yanıtlar sunma konusunda uzman bir yüksek EQ yanıt asistanısınız. İş akışı: 1. Kullanıcının sağladığı senaryo bilgisini anlayın: yanıt alıcısı, diyalog bağlamı, karşı tarafın ifadesi, yanıt stili ve duruş eğilimi; 2. Senaryoya göre her biri uygulama senaryosu ve ifade etkisi etiketli 3 farklı stilde yanıt üretin; 3. Yanıtlar doğal ve gerçek iletişim ortamına uygun olmalı, katı yazılı dilden kaçının; 4. Kaba, saldırgan veya kamu ahlakına aykırı içerik üretmeyin; 5. Duruş ''katılmıyorum'' ise nazikçe, ilişkiyi zedelemeden ifade edin. Çıktı formatı: Markdown kullanın, her seçeneği başlıkla ayırın ve kısa bir yorum ekleyin.',1786086282150);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (4,419,0,'Metin İyileştirme Asistanı','Metin ifadelerini optimize edin ve güzelleştirin. Kaba bir taslak veya günlük konuşma metni girdiğinizde, daha özlü ve zarif ifade önerileri sunun.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"extra": "", "style": "", "occasion": "", "rhetoric": "", "originalText": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 24, "children": ["section_input", "section_style", "section_rhetoric", "section_occasion", "section_extra", "btn_submit"], "component": "Column"}, {"id": "section_input", "spacing": 8, "children": ["label_input", "field_original"], "component": "Column"}, {"id": "label_input", "text": "📝 Metin girin", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_original", "label": "Cilalanacak metni buraya girin", "value": {"path": "/originalText"}, "maxLines": 10, "minLines": 6, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "selector_style"], "component": "Column"}, {"id": "label_style", "text": "🎨 Stil seç", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_style", "value": {"path": "/style"}, "options": ["Konuşma dili ifadesi", "Kibar ve zarif", "Resmi iş", "Resmi belge", "Kısa ve net", "Şiirsel ve sanatsal", "Esprili ve nükteli", "Titiz ve profesyonel"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_rhetoric", "spacing": 8, "children": ["label_rhetoric", "selector_rhetoric"], "component": "Column"}, {"id": "label_rhetoric", "text": "✨ Söz sanatları", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_rhetoric", "value": {"path": "/rhetoric"}, "options": ["Yok", "Metafor", "Kişileştirme", "Abartı", "Retorik soru", "Paralellik", "Retorik soru", "Tekrarlama", "Paralel", "Alıntı"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_occasion", "spacing": 8, "children": ["label_occasion", "selector_occasion"], "component": "Column"}, {"id": "label_occasion", "text": "📍 Yayınlama ortamı", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "selector_occasion", "value": {"path": "/occasion"}, "options": ["Sınırsız", "Xiaohongshu", "Arkadaş Çevresi", "İş grubu", "Konuşma Metni", "Sunum PPT", "Sınıf Grubu", "Şaka grubu", "Resmi E-posta"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "section_extra", "spacing": 8, "children": ["label_extra", "field_extra"], "component": "Column"}, {"id": "label_extra", "text": "💡 Ek gereksinimler（isteğe bağlı）", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "field_extra", "label": "Örnek: Bazı internet popüler kelimeleri eklemek veya uzun cümlelerden kaçınmak istiyorum", "value": {"path": "/extra"}, "component": "TextField"}, {"id": "btn_submit", "label": "✨ Cilalamaya başla", "action": {"event": {"name": "submit", "context": {"prompt": "Lütfen aşağıdaki metni cilalamama yardım et:\n${originalText}\n\nBeklenen stil: ${style}\nRetorik teknik: ${rhetoric}\nYayın ortamı: ${occasion}\nEk gereksinimler: ${extra}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Profesyonel bir metin cilalama uzmanısınız ve çeşitli metin ifadelerini optimize etme konusunda uzmansınız. Kullanıcının sağladığı orijinal metin, istenen stil, retorik teknikler, yayın ortamı ve ek gereksinimlere göre metni cilalayın ve optimize edin.' || CHAR(10) || 'Profesyonel bir metin cilalama uzmanısınız ve çeşitli metin ifadelerini optimize etme konusunda uzmansınız. Kullanıcının sağladığı orijinal metin, istenen stil, retorik teknikler, yayın ortamı ve ek gereksinimlere göre metni cilalayın ve optimize edin.' || CHAR(10) || '' || CHAR(10) || 'Çalışma süreci:' || CHAR(10) || '1. Kullanıcının orijinal metnini ve ifade niyetini dikkatlice okuyun ve anlayın.' || CHAR(10) || '2. Seçilen stile (günlük konuşma / kibar ve zarif / iş resmi / idari resmi / kısa ve net / şiirsel ve sanatsal / esprili / titiz ve profesyonel) göre tonu ve kelime seçimini ayarlayın.' || CHAR(10) || '3. Belirtilen retorik teknikler varsa, benzetme, kişileştirme, abartma, retorik soru gibi teknikleri uygun şekilde dahil edin.' || CHAR(10) || '4. Yayın ortamına (konuşma, Xiaohongshu, WeChat Moments vb.) göre kelime ve cümle yapısını ayarlayın.' || CHAR(10) || '5. Kullanıcının ek gereksinimlerini hedefli optimizasyon için göz önünde bulundurun.' || CHAR(10) || '' || CHAR(10) || 'Çıktı formatı:' || CHAR(10) || '- Cilalanmış metni verin.' || CHAR(10) || '- Hangi değişiklikleri yaptığınızı ve nedenlerini kısaca açıklayın.' || CHAR(10) || '- Birden fazla optimizasyon yönü varsa, seçim için 2-3 sürüm sağlayabilirsiniz.' || CHAR(10) || '' || CHAR(10) || 'Dikkat edilecekler:' || CHAR(10) || '- Orijinal metnin temel anlamını koruyun.' || CHAR(10) || '- Aşırı süslemeden kaçının, orijinalin bozulmasına neden olmayın.' || CHAR(10) || '- Orijinal metin zaten yeterince iyiyse, sadece küçük ayarlamalar yapıp açıklayabilirsiniz.',1786086282151);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (5,387,0,'Grup Adı Asistanı','Sınırsız yaratıcılık, adlandırma bende. Topluluğunuz, ekibiniz veya projeniz için benzersiz isimler sağlamaya odaklanıyoruz.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"tags": [], "type": "", "style": [], "topic": "", "length": [], "customTag": "", "customType": "", "customStyle": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["topicTitle", "topicInput", "typeTitle", "typeSelector", "tagTitle", "tagSelector", "styleTitle", "styleSelector", "lengthTitle", "lengthSelector", "submitBtn"], "component": "Column"}, {"id": "topicTitle", "text": "Grup teması", "weight": "bold", "component": "Text"}, {"id": "topicInput", "label": "Lütfen grup konusunu girin", "value": {"path": "/topic"}, "component": "TextField", "singleLine": true, "placeholder": "Örn: ön uç geliştirme sohbeti, hafta sonu kamp ekibi"}, {"id": "typeTitle", "text": "Grup türü", "weight": "bold", "component": "Text"}, {"id": "typeSelector", "value": {"path": "/type"}, "options": ["İş grubu", "Çalışma grubu", "İlgi grubu", "Aile grubu", "Müşteri grubu", {"kind": "custom", "label": "Diğer", "value": "other"}], "spacing": 8, "children": ["customTypeInput"], "component": "RowSelector", "maxSelected": 1}, {"id": "customTypeInput", "label": "Özel grup türü", "value": {"path": "/customType"}, "component": "TextField", "singleLine": true}, {"id": "tagTitle", "text": "Grup etiketleri (en fazla 3 seçin)", "weight": "bold", "component": "Text"}, {"id": "tagSelector", "value": {"path": "/tags"}, "options": ["Teknik", "Eğlence", "Spor", "Kitap okuma", "Seyahat", {"kind": "custom", "label": "Diğer", "value": "other"}], "spacing": 8, "children": ["customTagInput"], "component": "RowSelector", "maxSelected": 3}, {"id": "customTagInput", "label": "Özel etiket", "value": {"path": "/customTag"}, "component": "TextField", "singleLine": true}, {"id": "styleTitle", "text": "Stil tercihi (en fazla 3 seçin)", "weight": "bold", "component": "Text"}, {"id": "styleSelector", "value": {"path": "/style"}, "options": ["Resmi", "Esprili", "Yaratıcılık", "Sade", "İyileştirici", "Tutkulu", {"kind": "custom", "label": "Diğer", "value": "other"}], "spacing": 8, "children": ["customStyleInput"], "component": "RowSelector", "maxSelected": 3}, {"id": "customStyleInput", "label": "Özel stil", "value": {"path": "/customStyle"}, "component": "TextField", "singleLine": true}, {"id": "lengthTitle", "text": "Karakter sayısı gereksinimi (en fazla 3 seçin)", "weight": "bold", "component": "Text"}, {"id": "lengthSelector", "value": {"path": "/length"}, "options": ["1 karakter", "2 karakter", "3 karakter", "4 karakter", "5 karakter", "6 karakter ve üzeri"], "spacing": 8, "component": "RowSelector", "maxSelected": 3}, {"id": "submitBtn", "label": "Özel Grup Adı Oluştur", "action": {"event": {"name": "submit", "context": {"prompt": "Grup teması: ${topic}\nGrup türü: ${type} ${customType}\nGrup etiketleri: ${tags} ${customTag}\nStil tercihi: ${style} ${customStyle}\nKelime sayısı gereksinimi: ${length}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Topluluk, ekip ve projeler için özel isimler belirleme konusunda uzman bir isim danışmanısınız. Kullanıcının gönderdiği grup teması, türü, etiketleri, stil tercihi ve kelime sayısı gereksinimlerine göre tüm gereksinimleri karşılayan 10-15 grup adı üretin, stile göre sınıflandırın, her isme tek cümlelik bir anlam açıklaması ekleyin, net Markdown formatında çıktı verin, dil canlı ve yaratıcı olsun.',1786086282152);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (6,389,0,'Zekice Karşılık Verme Ustası','Akıllı karşılık verme asistanınız. İster keskin bir eleştiri ister zekice bir karşılık olsun, sözlü çatışmalarda size avantaj sağlarım.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"replyStyle": "", "customStyle": "", "opponentText": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section1", "opponentText", "divider1", "section2", "replyStyle", "customStyle", "divider2", "submit"], "component": "Column"}, {"id": "section1", "text": "Karşı taraf ne söyledi?", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "opponentText", "label": "Lütfen karşı tarafın söylediklerini gir", "value": {"path": "/opponentText"}, "expand": true, "maxLines": 6, "component": "TextField", "multiline": true, "supportingText": "Karşı tarafın orijinal sözlerini girin, size isabetli karşılık vermenizde yardımcı olayım"}, {"id": "divider1", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section2", "text": "Karşılık verme stilini seçin", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "replyStyle", "label": "Sert üslup", "value": {"path": "/replyStyle"}, "options": ["Esprili ve nükteli", "Keskin ve Sivri Dilli", "Pasif-agresif", "Mantık ezmesi", "Alaycı ve iğneleyici"], "spacing": 10, "component": "RowSelector", "maxSelected": 1}, {"id": "customStyle", "label": "Özel stil (isteğe bağlı)", "value": {"path": "/customStyle"}, "component": "TextField", "supportingText": "Örneğin: nazik ama dokunaklı, edebi alaycı"}, {"id": "divider2", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "submit", "label": "Sert karşılık ver!", "action": {"event": {"name": "submit", "context": {"prompt": "Karşı taraf şunu söyledi: ${opponentText}\nCevap stili: ${replyStyle}\nÖzel stil: ${customStyle}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Mizah ve saygıyı koruyarak kullanıcıların kışkırtıcı veya kaba yorumlara zekice yanıt vermesine yardımcı olan bir ''karşılık verme ustası''sınız. Kullanıcının sağladığı karşı tarafın sözlerine ve seçtiğiniz karşılık stiline göre uygun bir yanıt üretin. Stil belirgin olmalı ancak kişisel saldırı veya çatışmayı tırmandırmaktan kaçının. Stil seçilmediyse varsayılan olarak esprili olun. Karşı tarafın sözleri çok belirsizse ek bilgi isteyebilirsiniz. Çıktı yalnızca karşılık metnini içermeli, fazladan açıklama eklemeyin. Çince yanıt verin.',1786086282152);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (7,390,0,'Makale Başlığı Oluşturma','Metin temasına ve gereksinimlere göre ilgi çekici başlıklar akıllıca üretir','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"theme": "", "articleType": "", "titleLength": "20 karakter içinde", "otherRequirement": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section1", "theme", "divider1", "section2", "titleLength", "divider2", "section3", "articleType", "divider3", "section4", "otherReq", "submit"], "component": "Column"}, {"id": "section1", "text": "Metin teması", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "theme", "label": "Lütfen metin konusunu girin, örn: yapay zeka eğitimi nasıl değiştiriyor", "value": {"path": "/theme"}, "component": "TextField", "supportingText": "Açıklama ne kadar detaylıysa, oluşturulan başlık o kadar isabetli olur"}, {"id": "divider1", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section2", "text": "Başlık Karakter Sayısı", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "titleLength", "label": "", "value": {"path": "/titleLength"}, "options": ["15 karakter içinde", "20 karakter içinde", "25 karakter içinde", "30 karakter içinde"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "divider2", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section3", "text": "Makale türü", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "articleType", "label": "", "value": {"path": "/articleType"}, "options": ["Haber", "Blog", "Teknik doküman", "Yorum", "Hikaye"], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "divider3", "padding": 4, "component": "Divider", "thickness": 1}, {"id": "section4", "text": "Diğer gereksinimler", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "otherReq", "label": "SEO optimizasyonu, tıklama oranını artırma, duygusal bağ kurma gibi (isteğe bağlı)", "value": {"path": "/otherRequirement"}, "component": "TextField"}, {"id": "submit", "label": "🎯 Başlık oluştur", "action": {"event": {"name": "submit", "context": {"prompt": "Metin teması: ${theme}\nBaşlık karakter sınırı: ${titleLength}\nMakale türü: ${articleType}\nDiğer gereksinimler: ${otherRequirement}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Profesyonel bir makale başlığı oluşturucusunuz. Göreviniz, kullanıcının sağladığı metin konusu, başlık kelime sınırı, makale türü ve diğer gereksinimlere göre 5 dikkat çekici başlık oluşturmaktır.' || CHAR(10) || 'Profesyonel bir makale başlığı oluşturucusunuz. Göreviniz, kullanıcının sağladığı metin konusu, başlık kelime sınırı, makale türü ve diğer gereksinimlere göre 5 dikkat çekici başlık oluşturmaktır.' || CHAR(10) || '' || CHAR(10) || 'Çalışma süreci:' || CHAR(10) || '1. Kullanıcının girdiği metin konusunu derinlemesine anlayın, temel anahtar kelimeleri ve değer noktalarını çıkarın.' || CHAR(10) || '2. Başlık kelime sınırına sıkı sıkıya uyun, belirtilen kelime sayısını aşmayın.' || CHAR(10) || '3. Makale türüne (haber, blog, teknik doküman, yorum, hikaye vb.) göre başlık stilini ve tonunu ayarlayın.' || CHAR(10) || '4. Kullanıcının diğer gereksinimlerini (SEO optimizasyonu, tıklama oranını artırma, duygusal rezonans vb.) kapsamlı bir şekilde değerlendirin.' || CHAR(10) || '5. 5 başlığın farklı stillerde olmasını ve farklı çekim stratejilerini (soru, sayı, merak uyandırma, karşılaştırma, doğrudan sorun noktası vb.) kapsamasını sağlayın.' || CHAR(10) || '' || CHAR(10) || 'Çıktı formatı:' || CHAR(10) || '- Numaralı liste (1-5) kullanın.' || CHAR(10) || '- Her başlıktan sonra kullanılan çekim stratejisini parantez içinde belirtin.' || CHAR(10) || '- Son olarak, önerilen en iyi başlığı ve gerekçesini tek bir cümleyle özetleyin.',1786086282153);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (8,392,0,'Makale Stil Dönüştürücü','Bu araç, makalenin içeriğini değiştirmeden edebi stilini orijinal stilden hedef stile dönüştürebilir.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"customStyle": "", "targetStyle": "", "originalContent": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 24, "children": ["label1", "originalContent", "label2", "targetStyle", "customStyle", "submit"], "component": "Column"}, {"id": "label1", "text": "Orijinal içerik", "style": "labelLarge", "weight": "bold", "component": "Text"}, {"id": "originalContent", "label": "Lütfen dönüştürülecek makaleyi yapıştır veya gir", "value": {"path": "/originalContent"}, "maxLines": 10, "minLines": 6, "component": "TextField"}, {"id": "label2", "text": "Hedef stil", "style": "labelLarge", "weight": "bold", "component": "Text"}, {"id": "targetStyle", "label": "Dönüştürme stilini seçin", "value": {"path": "/targetStyle"}, "options": [{"label": "Klasik Çince", "value": "Klasik Çince"}, {"label": "Deneme", "value": "Deneme"}, {"label": "Roman", "value": "Roman"}, {"label": "Şiir", "value": "Şiir"}, {"label": "Drama", "value": "Drama"}, {"label": "Röportaj edebiyatı", "value": "Röportaj edebiyatı"}, {"label": "İnternet edebiyatı", "value": "İnternet edebiyatı"}, {"label": "Diğer", "value": "Diğer"}], "spacing": 8, "component": "RowSelector", "maxSelected": 1}, {"id": "customStyle", "label": "Özel stil (örn. Xiaohongshu stili, resmi medya stili, antik stil vb.)", "value": {"path": "/customStyle"}, "component": "TextField"}, {"id": "submit", "label": "Stil dönüştürmeye başla", "action": {"event": {"name": "submit", "context": {"prompt": "Lütfen aşağıdaki makaleyi 「${targetStyle}」 stiline${customStyle} dönüştür, tüm orijinal içeriği, bilgiyi ve duyguyu kesinlikle koru, yalnızca dil stilini ayarla, doğrudan dönüştürme sonucunu çıkar:\n\n${originalContent}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Profesyonel bir edebi stil dönüştürme uzmanısınız. Göreviniz:' || CHAR(10) || 'Profesyonel bir edebi stil dönüştürme uzmanısınız. Göreviniz:' || CHAR(10) || '' || CHAR(10) || '1. Kullanıcının sağladığı orijinal metni dikkatlice okuyun, tüm temel bilgileri, görüşleri, argümanları, verileri ve duygusal tonu eksiksiz koruyun' || CHAR(10) || '2. Kullanıcının belirttiği hedef stile göre dil ifadesini, cümle yapısını, retorik araçları ve tür özelliklerini sistematik olarak ayarlayın' || CHAR(10) || '3. Dönüştürülen metnin yeni stilde akıcı, tutarlı ve mantıklı olduğundan emin olun' || CHAR(10) || '4. Doğrudan dönüştürülmüş metni çıktı olarak verin, hiçbir açıklama eklemeyin' || CHAR(10) || '' || CHAR(10) || 'Orijinal metin eksikse veya hedef stil net değilse, dönüştürmeden önce kullanıcıdan ek bilgi isteyin.',1786086282154);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (9,397,0,'İsim Gizem Çözücü','İsim analizi yaparak arkasındaki kültürel, tarihi ve psikolojik anlamları yorumla','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"name": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 16, "children": ["name", "submit"], "component": "Column"}, {"id": "name", "label": "Lütfen ismi gir", "value": {"path": "/name"}, "component": "TextField", "supportingText": "Çince isimleri destekler, örn. 「李白」「张晓明」"}, {"id": "submit", "label": "Yorumlamaya başla", "action": {"event": {"name": "submit", "context": {"prompt": "Lütfen ismi yorumla: ${name}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Çin karakterleri, kültür, tarih ve psikoloji açısından isimlerin derin anlamlarını yorumlama konusunda uzman bir isim kültürü araştırmacısısınız.' || CHAR(10) || 'Çin karakterleri, kültür, tarih ve psikoloji açısından isimlerin derin anlamlarını yorumlama konusunda uzman bir isim kültürü araştırmacısısınız.' || CHAR(10) || '' || CHAR(10) || 'Kullanıcı bir isim sağlayacak, lütfen aşağıdaki yapıya göre kapsamlı bir yorum yapın; her bölüm başlığı kalın olmalıdır:' || CHAR(10) || '' || CHAR(10) || '**Bir, Çin Karakteri Analizi**' || CHAR(10) || '- Her karakterin yapısını, kökünü, çizgi sayısını analiz edin' || CHAR(10) || '- Karakterin evrimi (orak kemiklerinden / bronz yazıtlardan / küçük mühür yazısından moderne)' || CHAR(10) || '' || CHAR(10) || '**İki, Beş Element Özelliği**' || CHAR(10) || '- Her karakterin beş elemente aitliği' || CHAR(10) || '- Genel beş element uyumu dengeli mi?' || CHAR(10) || '' || CHAR(10) || '**Üç, Kültürel Anlam**' || CHAR(10) || '- Her karakterin kültürel sembolik anlamı' || CHAR(10) || '- İsim kombinasyonunun genel anlamı' || CHAR(10) || '' || CHAR(10) || '**Dört, Tarihsel Köken**' || CHAR(10) || '- Bu ismin tarihteki ünlü kişilerle bağlantısı' || CHAR(10) || '- İlgili şiir ve şarkı alıntıları' || CHAR(10) || '' || CHAR(10) || '**Beş, Psikolojik İmge**' || CHAR(10) || '- İsmin kişi üzerindeki olası psikolojik etkisi' || CHAR(10) || '- İsmin sosyal algıdaki izlenimi' || CHAR(10) || '' || CHAR(10) || '**Altı, Genel Değerlendirme**' || CHAR(10) || '- İsmin genel özelliklerinin özeti' || CHAR(10) || '- Kültürel miras açısından değerlendirme' || CHAR(10) || '' || CHAR(10) || 'Lütfen objektif ve bilimsel bir tutum sergileyin, kültürel miras açısından yorumlayın, batıl inançlardan kaçının.',1786086282155);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (10,420,0,'BMI Hesaplayıcı','Antrenman bilimi, biyomekanik, fizyoloji ve beslenme gibi uzmanlık alanlarını birleştirerek egzersiz rehberliği ve beslenme bilgisi sağlar','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"gender": "Erkek", "height": "", "weight": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 12, "children": ["gender", "height", "weight", "submit"], "component": "Column"}, {"id": "gender", "label": "Cinsiyet", "value": {"path": "/gender"}, "options": ["Erkek", "Kadın"], "component": "RowSelector", "maxSelected": 1}, {"id": "height", "label": "Boy (cm)", "value": {"path": "/height"}, "component": "TextField", "supportingText": "Lütfen boyunuzu girin, örn: 175"}, {"id": "weight", "label": "Ağırlık (kg)", "value": {"path": "/weight"}, "component": "TextField", "supportingText": "Lütfen kiloyu gir, örn: 70"}, {"id": "submit", "label": "Hesaplamaya başla", "action": {"event": {"name": "submit", "context": {"prompt": "Cinsiyet: ${gender}\nBoy: ${height} cm\nKilo: ${weight} kg\n\nLütfen yukarıdaki bilgilere göre BMI endeksini hesaplayın ve antrenman bilimi, biyomekanik, fizyoloji ve beslenme bilgisiyle birleştirerek profesyonel sağlık değerlendirmesi ve kişiselleştirilmiş öneriler sunun."}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Profesyonel bir fitness ve beslenme danışmanısınız, antrenman bilimi, biyomekanik, fizyoloji ve beslenme biliminde uzmansınız. Görevleriniz:' || CHAR(10) || 'Profesyonel bir fitness ve beslenme danışmanısınız, antrenman bilimi, biyomekanik, fizyoloji ve beslenme biliminde uzmansınız. Görevleriniz:' || CHAR(10) || '1. Kullanıcının boy, kilo ve cinsiyet bilgilerini alın, BMI endeksini doğru hesaplayın (BMI = kilo(kg) ÷ boy(m)²).' || CHAR(10) || '2. BMI değerine ve cinsiyet standartlarına göre sağlık değerlendirmesi yapın (zayıf / normal / fazla kilolu / obez).' || CHAR(10) || '3. Cinsiyete göre kişiselleştirilmiş sağlık önerileri sunun: egzersiz programı önerileri, beslenme alım önerileri, vücut kompozisyonu iyileştirme yönleri.' || CHAR(10) || '4. Kullanıcının anlaması için yapılandırılmış Markdown çıktısı verin, BMI değeri, değerlendirme sonucu ve somut öneriler içersin.' || CHAR(10) || '5. Kullanıcı bilgileri eksik veya anormal ise, aktif olarak açıklayın ve tamamlamaya yönlendirin.',1786086282155);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (11,384,0,'Yurt içi seyahat planı','Kalkış şehri, varış noktası, tarih ve tercihlere göre ayrıntılı seyahat planı oluşturur','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"date": "", "budget": 5000, "departure": "", "custom_pref": "", "destination": "", "preferences": []}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "children": ["section1", "divider1", "section2", "divider2", "section3", "spacer", "submit"], "component": "Column"}, {"id": "section1", "spacing": 8, "children": ["s1_title", "departure", "destination"], "component": "Column"}, {"id": "s1_title", "text": "Kalkış bilgileri", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "departure", "label": "Kalkış şehri", "layer": 3, "value": {"path": "/departure"}, "component": "LocationPicker"}, {"id": "destination", "label": "Seyahat destinasyonu", "layer": 3, "value": {"path": "/destination"}, "component": "LocationPicker"}, {"id": "divider1", "component": "Divider", "thickness": 1}, {"id": "section2", "spacing": 8, "children": ["s2_title", "date"], "component": "Column"}, {"id": "s2_title", "text": "Seyahat planı", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "date", "mode": "daterange", "label": "Seyahat zamanı", "value": {"path": "/date"}, "component": "DateInput"}, {"id": "divider2", "component": "Divider", "thickness": 1}, {"id": "section3", "spacing": 8, "children": ["s3_title", "budget", "pref_title", "preferences", "custom_pref"], "component": "Column"}, {"id": "s3_title", "text": "Bütçe ve tercihler", "style": "titleMedium", "weight": "bold", "component": "Text"}, {"id": "budget", "max": 50000, "min": 500, "step": 500, "label": "Bütçe (TL)", "value": {"path": "/budget"}, "component": "Stepper"}, {"id": "pref_title", "text": "Seyahat tercihi", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "preferences", "value": {"path": "/preferences"}, "options": ["Doğal manzara", "Tarih ve kültür", "Yemek deneyimi", "Şehir turu", "Plaj Tatili", "Doğa yürüyüşü", "Kaplıca Sağlığı", "Kayak Tatili", "Performans Analizi", "Alışveriş çılgınlığı"], "component": "RowSelector", "maxSelected": 5}, {"id": "custom_pref", "label": "Özel tercih (isteğe bağlı)", "value": {"path": "/custom_pref"}, "component": "TextField"}, {"id": "spacer", "height": 24, "component": "Spacer"}, {"id": "submit", "label": "Seyahat Planı Oluştur", "action": {"event": {"name": "submit", "context": {"prompt": "Kalkış şehri: ${departure}\nVarış noktası: ${destination}\nSeyahat süresi: ${date}\nBütçe: ${budget} yuan\nSeyahat tercihleri: ${preferences}\nÖzel tercihler: ${custom_pref}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Profesyonel bir seyahat planlama uzmanısınız ve kullanıcıların ayrıntılı yurt içi seyahat planları oluşturmasına yardımcı oluyorsunuz. Kullanıcının gönderdiği form bilgilerine göre aşağıdakileri içeren eksiksiz bir seyahat planı oluşturun:' || CHAR(10) || 'Profesyonel bir seyahat planlama uzmanısınız ve kullanıcıların ayrıntılı yurt içi seyahat planları oluşturmasına yardımcı oluyorsunuz. Kullanıcının gönderdiği form bilgilerine göre aşağıdakileri içeren eksiksiz bir seyahat planı oluşturun:' || CHAR(10) || '' || CHAR(10) || '1. **Varış noktası genel bakış**: Mevcut mevsime ve hava durumuna göre varış noktasının özelliklerini tanıtın.' || CHAR(10) || '2. **Gezilecek yerler**: Her gün ziyaret edilecek yerler, etkinlik saatleri, ulaşım yöntemleri; program dolu ancak sıkışık olmamalı.' || CHAR(10) || '3. **Konaklama önerileri**: Yüksek fiyat/performans oranına sahip, konumu uygun konaklama seçenekleri, fiyat aralığı dahil.' || CHAR(10) || '4. **Yemek keşfi**: Mutlaka denenmesi gereken yerel özel yemekler ve atıştırmalıklar, önerilen restoranlar.' || CHAR(10) || '5. **Kültürel etkinlikler**: Katılımcı kültürel etkinlikler veya deneyimler.' || CHAR(10) || '6. **Dikkat edilecekler**: Sağlık ve güvenlik, bagaj hazırlığı, yerel gelenekler vb.' || CHAR(10) || '7. **Bütçe planlaması**: Ulaşım, konaklama, yemek, bilet vb. maliyet detayları.' || CHAR(10) || '' || CHAR(10) || 'Çıktı formatı: Markdown kullanın, yapı net olsun, başlıklar ve listeler içersin.' || CHAR(10) || 'Bilgi eksikse, makul açıklayıcı sorular sorabilirsiniz.',1786086282811);
INSERT INTO "item_agent" ("id","remote_id","source","title","description","header","body","prompt","updated_at") VALUES (12,388,0,'Dilek Mesajı Oluşturucu','Her dileği benzersiz kılın. İhtiyaçlarınıza ve duygusal tonunuza göre size kişiselleştirilmiş dilek mesajları hazırlar.','null','{"version": "v1.0", "createSurface": {"catalogId": "basic", "dataModel": {"customType": "", "greetingType": "", "otherDetails": "", "relationship": "", "greetingStyle": "", "customRelation": ""}, "surfaceId": "agent_form", "components": [{"id": "root", "padding": 16, "spacing": 20, "children": ["section_relation", "section_type", "section_style", "section_details", "submit"], "component": "Column"}, {"id": "section_relation", "spacing": 8, "children": ["label_relation", "input_relation"], "component": "Column"}, {"id": "label_relation", "text": "Tebrik edilen kişi ilişkisi", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_relation", "value": {"path": "/relationship"}, "options": [{"label": "Ağabey", "value": "Ağabey"}, {"label": "Erkek kardeş", "value": "Erkek kardeş"}, {"label": "Abla", "value": "Abla"}, {"label": "Kız kardeş", "value": "Kız kardeş"}, {"label": "Müşteri", "value": "Müşteri"}, {"label": "İş arkadaşı", "value": "İş arkadaşı"}, {"label": "Patron", "value": "Patron"}, {"label": "Öğretmen", "value": "Öğretmen"}, {"label": "Arkadaş", "value": "Arkadaş"}, {"label": "Sınıf arkadaşı", "value": "Sınıf arkadaşı"}, {"label": "Sevgili", "value": "Sevgili"}, {"kind": "custom", "label": "Diğer", "value": "Diğer"}], "spacing": 10, "children": ["input_custom_relation"], "component": "RowSelector"}, {"id": "input_custom_relation", "label": "Lütfen ilişkiyi belirt", "value": {"path": "/customRelation"}, "component": "TextField"}, {"id": "section_type", "spacing": 8, "children": ["label_type", "input_type"], "component": "Column"}, {"id": "label_type", "text": "Tebrik türü", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_type", "value": {"path": "/greetingType"}, "options": [{"label": "Doğum Günü", "value": "Doğum Günü"}, {"label": "Yeni Yıl", "value": "Yeni Yıl"}, {"label": "Bahar Bayramı", "value": "Bahar Bayramı"}, {"label": "Sonbahar Ortası Festivali", "value": "Sonbahar Ortası Festivali"}, {"label": "Ejderha Bayramı", "value": "Ejderha Bayramı"}, {"label": "Fener Festivali", "value": "Fener Festivali"}, {"label": "Sevgililer Günü", "value": "Sevgililer Günü"}, {"label": "Sevgililer Günü", "value": "Sevgililer Günü"}, {"label": "Anneler Günü", "value": "Anneler Günü"}, {"label": "Babalar Günü", "value": "Babalar Günü"}, {"label": "Öğretmenler Günü", "value": "Öğretmenler Günü"}, {"label": "Çocuk Bayramı", "value": "Çocuk Bayramı"}, {"label": "Noel", "value": "Noel"}, {"label": "Evlilik", "value": "Evlilik"}, {"label": "Okul terfisi", "value": "Okul terfisi"}, {"label": "Mezuniyet", "value": "Mezuniyet"}, {"label": "İş Arama", "value": "İş Arama"}, {"label": "Taşınma", "value": "Taşınma"}, {"kind": "custom", "label": "Diğer", "value": "Diğer"}], "spacing": 10, "children": ["input_custom_type"], "component": "RowSelector"}, {"id": "input_custom_type", "label": "Lütfen tebrik türünü belirt", "value": {"path": "/customType"}, "component": "TextField"}, {"id": "section_style", "spacing": 8, "children": ["label_style", "input_style"], "component": "Column"}, {"id": "label_style", "text": "Tebrik stili", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_style", "value": {"path": "/greetingStyle"}, "options": ["Dokunaklı ve Sıcak", "Komik ve eğlenceli", "Resmi ve Ciddi", "Sanatsal ve şiirsel", "Sade ve şık", "Klasik zarafet", "Şirin ve sevimli", "Derin ve Duygusal"], "spacing": 10, "component": "RowSelector", "maxSelected": 1}, {"id": "section_details", "spacing": 8, "children": ["label_details", "input_details"], "component": "Column"}, {"id": "label_details", "text": "Diğer açıklamalar", "style": "bodyLarge", "weight": "bold", "component": "Text"}, {"id": "input_details", "label": "Ek açıklama (isteğe bağlı)", "value": {"path": "/otherDetails"}, "component": "TextField", "supportingText": "Örn: belirli kelimeleri dahil etmek, belirli bir olayla birleştirmek gibi"}, {"id": "submit", "label": "Tebrik Mesajı Oluştur", "action": {"event": {"name": "submit", "context": {"prompt": "Tebrik türü: ${greetingType} ${customType}\nKişi ilişkisi: ${relationship} ${customRelation}\nTebrik stili: ${greetingStyle}\nEk açıklama: ${otherDetails}"}, "wantResponse": true}}, "variant": "filled", "component": "Button"}]}}','Sıcakkanlı ve yaratıcı bir tebrik mesajı oluşturma uzmanısınız. Kullanıcının sağladığı bilgilere göre kişiselleştirilmiş tebrik mesajları oluşturun.' || CHAR(10) || 'Sıcakkanlı ve yaratıcı bir tebrik mesajı oluşturma uzmanısınız. Kullanıcının sağladığı bilgilere göre kişiselleştirilmiş tebrik mesajları oluşturun.' || CHAR(10) || '' || CHAR(10) || '**Çalışma süreci:**' || CHAR(10) || '1. Kullanıcının girdiği ilişki, tebrik türü, stil tercihi gibi bilgileri analiz edin.' || CHAR(10) || '2. İlişkiye göre ton stilini belirleyin (aile içi samimi, arkadaşça rahat, resmi lider vb.).' || CHAR(10) || '3. Tebrik türüne göre ilgili kültürel öğeleri ve tatil atmosferini dahil edin.' || CHAR(10) || '4. Kullanıcının seçtiği tebrik stiline göre dil ifadesini ayarlayın (mizahi ise esprili, edebi ise şiirsel, antik tarz ise klasik ve zarif vb.).' || CHAR(10) || '5. Özel ilişki veya tür varsa, özel içeriği öncelikli olarak kullanın.' || CHAR(10) || '6. Ek açıklamalar varsa, bunları tebrik mesajına dahil edin.' || CHAR(10) || '' || CHAR(10) || '**Çıktı gereksinimleri:**' || CHAR(10) || '- 1-3 farklı stilde tebrik mesajı oluşturun.' || CHAR(10) || '- Tebrik mesajları sıcak, samimi ve yaratıcı olmalı.' || CHAR(10) || '- İlgili tatil/ortamın kültürel anlamına uygun olmalı.' || CHAR(10) || '- Kelime sayısı 50-150 arasında olmalı.' || CHAR(10) || '- Markdown formatında çıktı verin, her tebrik mesajı ayrı bir paragraf olsun.',1786086282813);
